import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';
import { SHELL_WORKSPACE, shellReady } from '../shell/helpers.ts';

// The offline hold-to-talk voice recorder (#543). Chromium's fake media device stands in for the
// microphone. Baselines are only ever generated by the e2e workflow's `update_snapshots` dispatch
// (e2e/README.md).
const PATH = `/w/${SHELL_WORKSPACE}/today?capture=voice`;
const SHEET = '[data-slot="voice-sheet"]';
const VIEWPORTS = [
  { name: '360', width: 360, height: 740 },
  { name: '768', width: 768, height: 1024 },
  { name: '1280', width: 1280, height: 800 },
] as const;

test.describe('voice recorder sheet', { tag: '@a11y' }, () => {
  test.use({
    permissions: ['microphone'],
    launchOptions: {
      args: ['--use-fake-device-for-media-stream', '--use-fake-ui-for-media-stream'],
    },
  });

  test('records with tap-to-toggle, reviews and saves into the outbox', async ({
    page,
    asUser,
  }) => {
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await expect(sheet.getByText('Why we need your microphone')).toBeVisible();
    const button = sheet.locator('[data-slot="hold-to-talk"]');
    await button.focus();
    await page.keyboard.press('Space');
    await expect(sheet.locator('[data-slot="voice-announce"]')).toHaveText(/Recording, 00:0\d/);
    await page.waitForTimeout(1200);
    await page.keyboard.press('Space');
    await expect(sheet.getByRole('heading', { name: 'Review your note' })).toBeVisible();
    await sheet.getByRole('button', { name: 'Save' }).click();
    await expect(sheet.locator('[data-slot="voice-saved"]')).toBeVisible();
  });

  test('saves offline and says it will transcribe later', async ({ page, asUser, context }) => {
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await context.setOffline(true);
    const button = sheet.locator('[data-slot="hold-to-talk"]');
    await button.focus();
    await page.keyboard.press('Space');
    await page.waitForTimeout(1200);
    await page.keyboard.press('Space');
    await sheet.getByRole('button', { name: 'Save' }).click();
    await expect(
      sheet.getByText("Saved on this device. Will transcribe when you're back online."),
    ).toBeVisible();
  });

  test('Escape cancels and closes the sheet', async ({ page, asUser }) => {
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const button = page.locator(SHEET).locator('[data-slot="hold-to-talk"]');
    await button.focus();
    await page.keyboard.press('Space');
    await page.keyboard.press('Escape');
    await expect(page.locator(SHEET)).toHaveCount(0);
  });
});

test.describe('microphone permission denied', () => {
  test.use({ permissions: [] });

  test('shows how to enable it', async ({ page, asUser }) => {
    await page.addInitScript(() => {
      Object.defineProperty(navigator.mediaDevices, 'getUserMedia', {
        value: () => Promise.reject(new DOMException('denied', 'NotAllowedError')),
      });
    });
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await sheet.locator('[data-slot="hold-to-talk"]').click();
    await expect(sheet.getByText('Microphone access is off')).toBeVisible();
  });
});

for (const theme of ['light', 'dark'] as const) {
  for (const viewport of VIEWPORTS) {
    test(
      `voice recorder ${theme} ${viewport.name}`,
      { tag: '@visual' },
      async ({ page, asUser }, testInfo) => {
        const name = `voice-recorder-${theme}-${viewport.name}.png`;
        const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
        test.skip(
          testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
          'no baseline yet: dispatch the e2e workflow with update_snapshots',
        );
        await page.setViewportSize({ width: viewport.width, height: viewport.height });
        await page.emulateMedia({ colorScheme: theme });
        await asUser('owner', { path: PATH });
        await shellReady(page);
        await expect(page.locator(SHEET)).toHaveScreenshot(name);
      },
    );
  }
}
